// Gate worker for خصومات مستر بلاك. Serves the page only after a valid personal code.
// GATE_SECRET and STAFF_JSON are Worker environment bindings (not stored in this file).
const COOKIE = "mbgate";
const TITLE  = "خصومات مستر بلاك";
const MAXAGE = 60*60*24*30; // 30 days
const SECRET = globalThis.GATE_SECRET;
const STAFF  = JSON.parse(globalThis.STAFF_JSON);
const PAGE_B64 = "";

const enc = new TextEncoder();
async function hmac(msg){
  const key = await crypto.subtle.importKey('raw', enc.encode(SECRET), {name:'HMAC',hash:'SHA-256'}, false, ['sign']);
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(msg));
  return [...new Uint8Array(sig)].map(b=>b.toString(16).padStart(2,'0')).join('');
}
function b64urlEncode(s){ return btoa(unescape(encodeURIComponent(s))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); }
function b64urlDecode(s){ s=s.replace(/-/g,'+').replace(/_/g,'/'); return decodeURIComponent(escape(atob(s))); }
async function mkToken(name){
  const p = b64urlEncode(JSON.stringify({ n:name, exp: Math.floor(Date.now()/1000)+MAXAGE }));
  return p + '.' + await hmac(p);
}
async function checkToken(tok){
  if(!tok || tok.indexOf('.')<0) return null;
  const [p, sig] = tok.split('.');
  if(sig !== await hmac(p)) return null;
  try{ const o = JSON.parse(b64urlDecode(p)); if(o.exp < Math.floor(Date.now()/1000)) return null; return o; }catch(e){ return null; }
}
function cookies(req){ const h=req.headers.get('Cookie')||''; const o={}; h.split(';').forEach(c=>{const i=c.indexOf('='); if(i>0) o[c.slice(0,i).trim()]=c.slice(i+1).trim();}); return o; }
function pageHtml(){ return decodeURIComponent(escape(atob(PAGE_B64))); }

function loginPage(err){
  return `<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="robots" content="noindex, nofollow"><title>${TITLE}</title>
<style>:root{--bg:#111113;--surface:#1b1b1f;--fg:#f2f2f4;--muted:#9a9aa3;--line:#2e2e35;--accent:#c9a227}
*{box-sizing:border-box}html,body{margin:0;height:100%}
body{background:var(--bg);color:var(--fg);font-family:system-ui,"Segoe UI",Tahoma,sans-serif;display:flex;align-items:center;justify-content:center;padding:24px}
.box{display:flex;flex-direction:column;gap:14px;width:min(340px,88vw);text-align:center}
h1{font-size:1.25rem;margin:0 0 2px}p{color:var(--muted);font-size:.86rem;margin:0;line-height:1.6}
input{font-size:1.25rem;text-align:center;letter-spacing:.25em;text-transform:uppercase;padding:13px;border-radius:12px;background:var(--surface);color:var(--fg);border:1px solid var(--line);outline:none}
input:focus{border-color:var(--accent)}
button{background:var(--accent);color:#1a1405;border:none;font-weight:700;font-size:1rem;border-radius:12px;padding:13px;cursor:pointer}
.err{color:#e5595b;font-size:.82rem;min-height:1em}</style></head><body>
<form class="box" method="POST" action="/__login">
<h1>${TITLE}</h1><p>اكتب الكود الخاص بيك عشان تدخل.</p>
<input name="code" autocomplete="off" autocapitalize="characters" autofocus placeholder="••••••" maxlength="12">
<button type="submit">دخول</button><div class="err">${err||''}</div>
</form></body></html>`;
}

addEventListener('fetch', event => event.respondWith(handle(event.request)));
async function handle(req){
  const url = new URL(req.url);
  if(url.pathname === '/__logout'){
    return new Response(null, {status:302, headers:{'Location':'/','Set-Cookie':`${COOKIE}=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Lax`}});
  }
  if(req.method === 'POST' && url.pathname === '/__login'){
    const form = await req.formData();
    const supplied = String(form.get('code')||'').trim().toUpperCase();
    const name = STAFF[supplied];
    if(!name) return new Response(loginPage('الكود غلط — جرّب تاني أو كلّم المسؤول.'), {status:401, headers:{'Content-Type':'text/html; charset=utf-8'}});
    const tok = await mkToken(name);
    return new Response(null, {status:302, headers:{'Location':'/','Set-Cookie':`${COOKIE}=${tok}; Path=/; Max-Age=${MAXAGE}; HttpOnly; Secure; SameSite=Lax`}});
  }
  const sess = await checkToken(cookies(req)[COOKIE]);
  if(!sess) return new Response(loginPage(''), {status:200, headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'}});
  return new Response(pageHtml(), {status:200, headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Robots-Tag':'noindex'}});
}
